use fusion_lab::{DeliveryError, DeliveryOutcome, Error, Observation, ReplayModel, Sensor, Trace, replay_delivery};
fn trace(v_arrival: u32) -> Trace { Trace::new(3, 128, [None, None], vec![Observation::new(Sensor::Position, 0, 0, 0, [1e308, 1e308]).unwrap(), Observation::new(Sensor::Velocity, 0, 0, v_arrival, [1e308, 1e308]).unwrap()]).unwrap() }
fn main() { let policy=replay_delivery(&ReplayModel::new(5.0,2.0,0.0).unwrap(), &Trace::new(1,128,[None,None],vec![Observation::new(Sensor::Position,0,0,0,[1e308,1e308]).unwrap(),Observation::new(Sensor::Velocity,0,0,0,[1e308,1e308]).unwrap()]).unwrap()).expect("original-model one-second baseline-policy check"); let first=policy.snapshots().iter().find(|s|!s.integrated_position().into_iter().all(f64::is_finite)).map(|s|s.tick()); assert!(policy.snapshots().iter().all(|s|s.estimate().position.into_iter().chain(s.estimate().velocity).chain(s.covariance().iter().flatten().copied()).all(f64::is_finite))); println!("BASELINE_POLICY_OK first_nonfinite_raw_integration_tick={first:?} filter_all_finite=true snapshots={}",policy.snapshots().len()); let model=ReplayModel::new(0.0,0.0,0.0).unwrap(); match replay_delivery(&model,&trace(0)) { Err(DeliveryError::NumericalFailure {tick,observation:None,source:Error::NumericalFailure}) => {println!("ONTIME_ERROR tick={tick} observation=None source=NumericalFailure");assert_eq!(tick,80);}, other => panic!("unexpected all-on-time result: {other:?}") } let late=replay_delivery(&model,&trace(300)).expect("stale comparator must succeed");assert_eq!(late.snapshots().len(),301);assert!(late.snapshots().iter().all(|s| s.estimate().position.into_iter().chain(s.estimate().velocity).chain(s.covariance().iter().flatten().copied()).chain(s.held_position()).chain(s.integrated_position()).all(f64::is_finite)));assert_eq!(late.ledger()[0].outcome(),DeliveryOutcome::Accepted);assert_eq!(late.ledger()[1].outcome(),DeliveryOutcome::StaleDrop);let last=late.snapshots().last().unwrap();println!("DELAYED_SUCCESS snapshots={} pos={:?} vel={:?} held={:?} integrated={:?} Vdecision={} Voutcome={:?}",late.snapshots().len(),last.estimate().position,last.estimate().velocity,last.held_position(),last.integrated_position(),late.ledger()[1].decision_tick(),late.ledger()[1].outcome()); }
